const fs=require('node:fs'),path=require('node:path'),crypto=require('node:crypto');
function makeTool(){const root=path.resolve(__dirname,'../..');const manifest=JSON.parse(fs.readFileSync(path.join(root,'shared/fixtures/manifest.valid.json')));const contract=JSON.parse(fs.readFileSync(path.join(root,'shared/fixtures/contract.valid.json')));contract.actions[0].id='multiply';const wasm=fs.readFileSync(path.join(root,'tests/spikes/core-guest/target/wasm32-unknown-unknown/release/kortex_core_guest_spike.wasm'));
 const crc=b=>{let c=0xffffffff;for(const n of b){c^=n;for(let i=0;i<8;i++)c=c>>>1^((c&1)?0xedb88320:0)}return(c^0xffffffff)>>>0};const locals=[],central=[];let offset=0;
 for(const[name,data]of [['manifest.json',Buffer.from(JSON.stringify(manifest))],['contract.json',Buffer.from(JSON.stringify(contract))],['module.wasm',wasm],['assets/icon.svg',Buffer.from('<svg xmlns="http://www.w3.org/2000/svg"/>')]]){const n=Buffer.from(name),l=Buffer.alloc(30),c=Buffer.alloc(46);l.writeUInt32LE(0x04034b50);l.writeUInt16LE(20,4);l.writeUInt32LE(crc(data),14);l.writeUInt32LE(data.length,18);l.writeUInt32LE(data.length,22);l.writeUInt16LE(n.length,26);c.writeUInt32LE(0x02014b50);c.writeUInt16LE(20,4);c.writeUInt16LE(20,6);c.writeUInt32LE(crc(data),16);c.writeUInt32LE(data.length,20);c.writeUInt32LE(data.length,24);c.writeUInt16LE(n.length,28);c.writeUInt32LE(offset,42);locals.push(l,n,data);central.push(c,n);offset+=l.length+n.length+data.length;}
 const directory=Buffer.concat(central),end=Buffer.alloc(22);end.writeUInt32LE(0x06054b50);end.writeUInt16LE(4,8);end.writeUInt16LE(4,10);end.writeUInt32LE(directory.length,12);end.writeUInt32LE(offset,16);const bytes=Buffer.concat([...locals,directory,end]);const pair=crypto.generateKeyPairSync('ed25519');const sha256=crypto.createHash('sha256').update(bytes).digest('hex');const descriptor={schema_version:1,tool_id:manifest.id,version:manifest.version,abi_version:'1.0',sha256,signing_key_id:'ephemeral-fixture',signature:crypto.sign(null,Buffer.from(`kortex-artifact-v1\n${manifest.id}\n${manifest.version}\n1.0\n${sha256}\n`),pair.privateKey).toString('base64')};const pub=pair.publicKey.export({format:'der',type:'spki'}).subarray(-32).toString('base64');return{bytes,descriptor,trust:{'ephemeral-fixture':pub},keys:[{id:'ephemeral-fixture',public_key_base64:pub,not_before:0,expires:Date.now()+86400000,revoked:false}]};}
module.exports={makeTool};
if(require.main===module){const fixture=makeTool(),dir=path.resolve(__dirname,'../../target/desktop-fixture');fs.mkdirSync(dir,{recursive:true});fs.writeFileSync(path.join(dir,'demo.tool'),fixture.bytes);fs.writeFileSync(path.join(dir,'demo.tool.json'),JSON.stringify(fixture.descriptor));fs.writeFileSync(path.join(dir,'trust.json'),JSON.stringify(fixture.trust));console.log(dir);}
